     5	import hotel.reservations.ReservationStore;
     6	import java.math.BigDecimal;
     7	import java.time.YearMonth;
     8	import java.util.ArrayList;
     9	import java.util.List;
    10	
    11	public final class RatePlansReport {
    12	
    13	    private final ReservationStore store;
    14	
    15	    public RatePlansReport(ReservationStore store) {
    16	        this.store = store;
    17	    }
    18	
    19	    public String generate(YearMonth month) {
    20	        int standardCount = 0;
    21	        BigDecimal standardAmount = BigDecimal.ZERO.setScale(2);
    22	        int nonRefundableCount = 0;
    23	        BigDecimal nonRefundableAmount = BigDecimal.ZERO.setScale(2);
    24	
    25	        for (Reservation reservation : store.all()) {
    26	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
    27	            if (reservation.isPaid() && startsInMonth) {
    28	                if (reservation.ratePlan() == RatePlan.STANDARD) {
    29	                    standardCount++;
    30	                    standardAmount = standardAmount.add(reservation.amountKept());
    31	                } else if (reservation.ratePlan() == RatePlan.NON_REFUNDABLE) {
    32	                    nonRefundableCount++;
    33	                    nonRefundableAmount = nonRefundableAmount.add(reservation.amountKept());
    34	                }
    35	            }
    36	        }
    37	
    38	        StringBuilder csv = new StringBuilder();
    39	        csv.append("Pousada Maré Alta,rate-plans,").append(month).append('\n');
    40	        csv.append("rate_plan,reservations,amount\n");
    19	    public String generate(YearMonth month) {
    20	        List<Reservation> taxable = new ArrayList<>();
    21	        for (Reservation reservation : store.all()) {
    22	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
    23	            if (reservation.isPaid() && startsInMonth) {
    24	                taxable.add(reservation);
    25	            }
    26	        }
    27	        taxable.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
    28	
    29	        StringBuilder csv = new StringBuilder();
    30	        csv.append("Pousada Maré Alta,tourism-tax,").append(month).append('\n');
    31	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
    32	        BigDecimal totalTax = BigDecimal.ZERO.setScale(2);
    33	        for (Reservation reservation : taxable) {
    34	            BigDecimal tax = calculateTax(reservation.guests(), reservation.price().nights());
    35	            csv.append(reservation.id()).append(',')
    36	                    .append(reservation.roomNumber()).append(',')
    37	                    .append(reservation.checkIn()).append(',')
    38	                    .append(reservation.checkOut()).append(',')
    39	                    .append(reservation.guests()).append(',')
    40	                    .append(reservation.price().nights()).append(',')
    41	                    .append(tax.toPlainString()).append('\n');
    42	            totalTax = totalTax.add(tax);
    43	        }
    44	        csv.append("total,").append(totalTax.toPlainString()).append('\n');
    45	        return csv.toString();
    46	    }
    47	
    48	    private BigDecimal calculateTax(int guests, int nights) {
    49	        BigDecimal taxPerNightPerGuest = new BigDecimal("4.50");
    50	        return taxPerNightPerGuest.multiply(BigDecimal.valueOf(guests * nights)).setScale(2, java.math.RoundingMode.HALF_EVEN);
    51	    }
    52	}
